function RadioOption({ id, name, value, label }) {
  const option = document.createElement('li');
  option.className = 'radio-option';

  const input = document.createElement('input');
  input.type = 'radio';
  input.id = id;
  input.name = name;
  input.value = value;

  const labelEl = document.createElement('label');
  labelEl.htmlFor = id;

  const indicator = document.createElement('span');
  indicator.className = 'radio-indicator';
  indicator.setAttribute('aria-hidden', 'true');

  const text = document.createElement('span');
  text.className = 'radio-label-text';
  text.textContent = label;

  labelEl.appendChild(indicator);
  labelEl.appendChild(text);
  option.appendChild(input);
  option.appendChild(labelEl);

  return option;
}

function NotificationForm() {
  const card = document.createElement('div');
  card.className = 'card';
  card.setAttribute('role', 'main');

  const title = document.createElement('h1');
  title.className = 'card-title';
  title.textContent = 'Preferences';

  const subtitle = document.createElement('p');
  subtitle.className = 'card-subtitle';
  subtitle.textContent = 'Customize how you stay informed.';

  const form = document.createElement('form');
  form.id = 'preferences-form';
  form.setAttribute('novalidate', '');

  // form-field wrapper
  const formField = document.createElement('div');
  formField.className = 'form-field';

  const fieldset = document.createElement('fieldset');
  fieldset.style.border = 'none';
  fieldset.style.padding = '0';

  const legend = document.createElement('legend');
  legend.textContent = 'How do you prefer to receive notifications?';

  const options = [
    { id: 'notif-email', value: 'email', label: 'Email' },
    { id: 'notif-sms', value: 'sms', label: 'SMS' },
    { id: 'notif-push', value: 'push', label: 'Push Notifications' },
  ];

  const ul = document.createElement('ul');
  ul.className = 'radio-group';
  ul.setAttribute('role', 'radiogroup');

  options.forEach(({ id, value, label }) => {
    ul.appendChild(RadioOption({ id, name: 'notification', value, label }));
  });

  fieldset.appendChild(legend);
  fieldset.appendChild(ul);
  formField.appendChild(fieldset);

  const submitBtn = document.createElement('button');
  submitBtn.type = 'submit';
  submitBtn.className = 'submit-btn';
  submitBtn.textContent = 'Save Preferences';

  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.setAttribute('role', 'status');
  toast.setAttribute('aria-live', 'polite');

  form.appendChild(formField);
  form.appendChild(submitBtn);
  form.appendChild(toast);

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const selected = form.querySelector('input[name="notification"]:checked');
    toast.className = 'toast';

    if (!selected) {
      toast.className = 'toast error';
      toast.textContent = '⚠ Please select a notification preference before submitting.';
      return;
    }

    const labels = { email: 'Email', sms: 'SMS', push: 'Push Notifications' };
    toast.className = 'toast success';
    toast.textContent = `✓ Saved! You'll receive notifications via ${labels[selected.value]}.`;
  });

  card.appendChild(title);
  card.appendChild(subtitle);
  card.appendChild(form);

  return card;
}

function App() {
  const root = document.getElementById('root');
  root.appendChild(NotificationForm());
}

App();
